payload:=jsonb_build_object('p_against_ledger_id',party,'p_cash_bank_ledger_id',cash,'p_amount',0.01,'p_ref_no','ROLLBACK-RAWGUARD-PAY','p_narration','Rollback protected guard','p_data_mode','TEST');
